// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // Keep domain wide but meaningful: depositor must not be zero address
        vm.assume(depositor != address(0));
        // Ensure depositor has enough ETH to send
        vm.deal(depositor, amt);

        // Read MinDeposit from contract
        uint256 min = c.MinDeposit();

        // We are testing the universal property: for any input, reference only updates balances when msg.value > MinDeposit.
        // To let fuzzer find a counterexample for the mutant, we do nothing special here — the fuzzer will try amt == min.

        // Record balance mapping for depositor before
        uint256 before = c.balances(depositor);

        // Perform the deposit as the depositor
        vm.prank(depositor);
        bool ok;
        try c.Deposit{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, read balances
        uint256 after = c.balances(depositor);

        // The universal property expected from the reference contract:
        // If msg.value <= MinDeposit then balances must NOT increase (i.e., after == before).
        // The mutant that uses >= will increase balances when msg.value == MinDeposit, breaking this property.
        if (amt <= min) {
            assertTrue(after == before);
        } else {
            // For amt > min, reference may accept and increase balances (or call may revert if something else); we can't assert increase here universally.
            // So assert a trivially true condition to keep single assert structure per instructions by placing it inside else branch.
            assertTrue(true);
        }
    }
}

