pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: depositor address and amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // Keep domain wide but ensure amt is a reasonable ETH-like value
        // allow zero too; we don't want to exclude MinDeposit itself
        // cap to avoid extremely large vm.deal cost
        amt = bound(amt, 0, 10 ether);

        // Ensure depositor has funds to send
        vm.deal(depositor, amt);

        // Snapshot balances mapping for an arbitrary key: choose an address key also fuzzed as depositor
        // The general rule concerns that no balances[key] increases when msg.value <= MinDeposit.
        // We'll observe c.balances(depositor) before and after a Deposit call made by 'depositor'.
        uint256 before = c.balances(depositor);

        // Make the deposit call as depositor, sending amt wei
        vm.prank(depositor);
        // Use try/catch to avoid bubbling reverts; Deposit in reference and mutant don't revert on low value
        try c.Deposit{value: amt}() {
            // noop
        } catch {
            // noop
        }

        uint256 after = c.balances(depositor);

        // The universal property: if amt <= MinDeposit, reference C will NOT increase balances[depositor].
        // We express that as: for all inputs, after <= before when amt <= MinDeposit.
        // The mutant (>=) will increase when amt == MinDeposit; thus this assertion will fail for some inputs on the mutant.
        uint256 Min = c.MinDeposit();
        if (amt <= Min) {
            assertTrue(after <= before);
        } else {
            // if amt > MinDeposit, reference may increase; we don't constrain that case
            assertTrue(true);
        }
    }
}

