pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: an actor and an amount. We keep domain wide but ensure nonzero address and amount sized
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep actor non-zero and not the contract itself
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Bound amount to reasonable range to avoid overflow in vm.deal and to allow paying MinDeposit
        uint256 amt = bound(amount, 0, 10 ether);

        // Ensure we test the critical case where amount == MinDeposit as well as other values.
        // Do not exclude equality — the property concerns behavior at exactly MinDeposit.

        // Fund the actor so they can send ETH
        vm.deal(actor, amt);

        // Read a storage key that might differ: choose some arbitrary key derived from actor
        // We will read balances(actor) before and after deposit on the reference contract.
        uint256 before = c.balances(actor);

        // Make the call as the actor, sending amt
        vm.prank(actor);
        // perform payable call; use try/catch to capture reverts (Deposit does not revert in reference)
        bool ok;
        try c.Deposit{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = c.balances(actor);

        // General property (single assert): For the reference contract, if the sent amount is exactly MinDeposit,
        // the reference SHOULD NOT change any stored balances; i.e., balances(actor) must equal before for ALL inputs.
        // The mutant that uses '>=' will sometimes make this assertion fail when amt == MinDeposit.
        // We assert the property on the reference by checking balances unchanged when amt == MinDeposit.
        // Accept all other cases as unconstrained by this universal rule.
        if (amt == c.MinDeposit()) {
            // For the reference contract this must always hold
            assertTrue(after == before);
        } else {
            // If not the exact threshold, we still assert nothing about balances; to keep a single assert
            // that always holds on reference we assert that the contract call did not revert (reference never reverts)
            // This secondary branch still uses a property the reference satisfies for all admissible inputs.
            assertTrue(ok == true);
        }
    }
}

