pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz params: depositor address and amount to send
    function testFuzz_property(address depositor, uint256 amount) public {
        // Keep depositor non-zero to be a valid actor
        vm.assume(depositor != address(0));
        // Bound amount to a reasonable range so we can vm.deal and send funds.
        // Allow very large but bounded so test remains wide.
        amount = bound(amount, 0, 10 ether);

        // The reference contract's rule: if msg.value > MinDeposit then balances[msg.sender] increases by msg.value.
        // We exercise a deposit where msg.value > MinDeposit to trigger the intended branch in the reference.
        uint256 minDep = c.MinDeposit();
        vm.assume(amount > minDep); // ensure we target the branch that should update balance in reference

        // Fund the depositor and make the deposit call as that sender
        vm.deal(depositor, amount);
        vm.prank(depositor);
        // Call Deposit with value; capture whether call succeeded (should succeed in both versions)
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: after making a deposit with msg.value > MinDeposit, the reference guarantees
        // depositor's stored balance equals amount (since started from zero) — we read that public getter.
        // The mutant inverts the gate and for such an amount may leave the stored balance at zero, breaking this rule.
        assertTrue(ok && c.balances(depositor) == amount);
    }
}

