pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor and amount. We keep domain wide but ensure amount fits an admissible case
    function testFuzz_property(address actor, uint256 amount) public {
        // admissible domain: actor must be non-zero, amount at least MinDeposit and not absurdly large
        vm.assume(actor != address(0));
        // Keep amount bounded so vm.deal and transferable ETH is reasonable
        amount = bound(amount, 1 wei, 10 ether);

        // Reference contract's MinDeposit is 1 ether. We want to exercise the branch where msg.value >= MinDeposit
        // Ensure we fuzz amounts that are >= MinDeposit so reference should update balances for caller
        vm.assume(amount >= 1 ether);

        // Fund actor so they can send `amount`
        vm.deal(actor, amount);

        // Record balance before deposit
        uint256 before = c.balances(actor);

        // Perform Deposit from actor sending `amount`
        vm.prank(actor);
        // call Deposit payable
        try c.Deposit{value: amount}() {
            // success
        } catch {
            // In reference, Deposit with amount >= MinDeposit uses internal require only for overflow check which cannot fail here
            // So it should not revert; but keep test general: if it reverts, ok flag remains as is
        }

        // Exactly one assertion: reference guarantees that deposits >= MinDeposit increase the caller's stored balance by amount
        // Read c via its public getter balances(actor)
        assertTrue(c.balances(actor) == before + amount);
    }
}

