import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint constant ONE = 1 ether;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor address and amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // Keep amount in a wide but meaningful domain: allow amounts >= 0 and reasonably bounded
        // We want to target the behavior around MinDeposit which is 1 ether.
        // Ensure depositor is not zero to be a valid actor
        vm.assume(depositor != address(0));
        // bound amount to avoid overflow issues in vm.deal and to keep test meaningful
        amount = bound(amount, 0, 10 ether);

        // We assert a universal property about the reference contract C:
        // If msg.value >= MinDeposit (1 ether) then Deposit increases balances[depositor] by msg.value.
        // So we set up the depositor with amount, call Deposit, and check the public getter balances.

        // Give depositor ETH to perform the deposit
        vm.deal(depositor, amount);

        // Record balance before
        uint before = c.balances(depositor);

        // Make the call as depositor with the fuzzed amount
        vm.prank(depositor);
        c.Deposit{value: amount}();

        uint after = c.balances(depositor);

        // The single universal assertion: if amount >= MinDeposit then after == before + amount
        // This holds for the reference contract for all inputs; the mutant (which uses msg.value < MinDeposit)
        // will violate this for some inputs (e.g., amount >= 1 ether).
        if (amount >= ONE) {
            assertTrue(after == before + amount);
