pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor (who sends Ether), amount (msg.value), key (the address whose balance we will observe)
    function testFuzz_property(address depositor, uint256 amount, address key) public {
        // Keep amounts within a reasonable range to avoid overflow in balances arithmetic
        uint256 boundedAmount = bound(amount, 0, 10 ether);
        // Ensure depositor has funds to send
        vm.deal(depositor, boundedAmount);

        // Record balance at key before deposit
        uint256 before = c.balances(key);

        // Make the deposit from depositor
        vm.prank(depositor);
        // call Deposit with boundedAmount wei
        c.Deposit{value: boundedAmount}();

        // Record balance at key after deposit
        uint256 after = c.balances(key);

        // General rule (one assertion): For the correct contract, if the depositor is the observed key
        // and the deposit amount is strictly greater than MinDeposit, then after == before + amount.
        // This assertion reads only c's public getter balances and MinDeposit via c.MinDeposit().
        // It is universally true for the reference implementation and is broken by the mutant
        // which inverts the comparison (msg.value < MinDeposit).
        uint256 minDep = c.MinDeposit();

        if (depositor == key && boundedAmount > minDep) {
            assertTrue(after == before + boundedAmount);
        } else {
            // In the other cases (different key, or small deposit) reference makes no guaranteed change to this key,
            // so require that balances didn't unexpectedly decrease (sanity): after >= before
            assertTrue(after >= before);
        }
    }
}

