pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: actor (the depositor) and amount (msg.value)
    function testFuzz_property(address actor, uint256 amount) public {
        // Keep actor non-zero and amount in a wide domain; allow large amounts to exercise overflow
        vm.assume(actor != address(0));

        // We must ensure amount is payable and can be sent by actor
        // Let the fuzzer choose any amount >= 0; fund the actor with that amount (bounded to avoid over/underflow in vm.deal)
        uint256 bounded = bound(amount, 0, type(uint128).max); // keep vm.deal amounts reasonable but wide
        vm.deal(actor, bounded);

        // Read old balance for the actor from contract
        uint256 oldBal = c.balances(actor);

        // Perform the Deposit call as actor with value = bounded
        vm.prank(actor);
        // call Deposit with provided value, catching any reverts
        bool ok;
        try c.Deposit{value: bounded}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the reference implementation guarantees that if the call succeeded
        // and bounded > MinDeposit, then balances[actor] == oldBal + bounded.
        // We assert this universal property (the mutant that removed the overflow check can violate it for some inputs).

        // If the call reverted or the deposit was ignored due to bounded <= MinDeposit, the property is that
        // balances remain equal to oldBal. We combine these into a single check using the public getter.

        uint256 newBal = c.balances(actor);
        uint256 minDeposit = c.MinDeposit();

        if (!ok) {
            // If the deposit call reverted, reference ensures no state change: balances unchanged
            assertTrue(newBal == oldBal);
        } else {
            if (bounded > minDeposit) {
                // successful deposit and value exceeded MinDeposit: balance must increase by exactly bounded
                assertTrue(newBal == oldBal + bounded);
            } else {
                // deposit path ignored (if msg.value <= MinDeposit), balances unchanged
                assertTrue(newBal == oldBal);
            }
        }
    }
}

