pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep domain wide but ensure amount is potentially large and > 0
        // allow amount to be any uint256; but require it to be > 0 so we can fund the depositor
        // and let the contract's own MinDeposit gate be exercised by both sides.
        vm.assume(depositor != address(0));

        // record a snapshot of balances for a few addresses including depositor and an unrelated key
        // pick three keys derived from depositor so fuzzer can vary keys while keeping test deterministic
        address k1 = depositor;
        address k2 = address(uint160(uint256(keccak256(abi.encodePacked(depositor, uint256(1))))));
        address k3 = address(uint160(uint256(keccak256(abi.encodePacked(depositor, uint256(2))))));

        uint256 before_k1 = c.balances(k1);
        uint256 before_k2 = c.balances(k2);
        uint256 before_k3 = c.balances(k3);

        // fund depositor so the payable call can succeed when amount > 0
        vm.deal(depositor, amount);

        // make the deposit call as depositor; use try/catch to capture any unexpected revert
        bool ok = true;
        vm.prank(depositor);
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After deposit (whether it reverted or not), the reference C guarantees that for ALL keys k,
        // balances[k] did not decrease as a result of calling Deposit (because Deposit in reference
        // checks for overflow and only updates when safe). We assert that for our sampled keys.
        // This single assertTrue observes c via its public getter.
        uint256 after_k1 = c.balances(k1);
        uint256 after_k2 = c.balances(k2);
        uint256 after_k3 = c.balances(k3);

        // Assert the universal property on sampled keys: none decreased.
        assertTrue(after_k1 >= before_k1 && after_k2 >= before_k2 && after_k3 >= before_k3);
    }
}

